pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // addr: the depositor / collector
    // depositAmt: amount to deposit (must be >0 to be meaningful)
    // collectAmt: amount to attempt to collect
    function testFuzz_property(address addr, uint256 depositAmt, uint256 collectAmt) public {
        // Keep params in wide admissible domain
        vm.assume(addr != address(0));
        depositAmt = bound(depositAmt, 0, 1 ether);
        collectAmt = bound(collectAmt, 0, 1 ether);

        // Fund the actor so they can send Ether to c
        vm.deal(addr, depositAmt + 1 ether);

        // Actor makes a deposit via Deposit (use payable call)
        vm.prank(addr);
        c.Deposit{value: depositAmt}();

        // Record balance mapping before calling Collect
        uint256 before = c.balances(addr);

        // Ensure MinSum is low enough so that Collect may proceed: set MinSum to 0 before Initialized
        // SetMinSum can only be called before Initialized; this is allowed by reference contract.
        c.SetMinSum(0);

        // Now call Collect as the same actor; Collect will attempt to send ether back
        bool ok;
        vm.prank(addr);
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // After Collect completes (whether success or revert), the reference property we assert:
        // If Collect returned (ok==true), the recorded stored balance must be >= before - collectAmt
        // but more directly: in the correct contract, balances never increase/decrease unexpectedly due to Deposit bug;
        // we assert that the stored balances(addr) is >= before - collectAmt (underflow guarded by contract logic)
        // This property holds for the reference for all inputs; the mutant (which decrements on Deposit)
        // can make this fail for some inputs (fuzzer will find them).
        uint256 after = c.balances(addr);

        // Single required assertion: read-only observation on c
        // For safety, compute expected lower bound and assert
        if (ok) {
            // If Collect succeeded, after should be equal to before - collectAmt in the correct contract
            // but to be tolerant in case Collect didn't transfer (ok==false) we only assert a weaker universal property:
            assertTrue(after + collectAmt == before || after + collectAmt < before + 1, "balance invariant violated");
        } else {
            // If Collect reverted, the balances must be unchanged in the reference implementation
            assertTrue(after == before, "balance changed despite reverted Collect");
        }
    }
}

