import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor addr, initial deposit amount, collect amount
    function testFuzz_property(address depositor, uint256 depositAmt, uint256 collectAmt) public {
        // keep domain reasonable and avoid trivial zeros that don't exercise behavior
        depositAmt = bound(depositAmt, 1, 1 ether);
        collectAmt = bound(collectAmt, 1, 1 ether);
        depositor = address(uint160(uint256(keccak256(abi.encodePacked(depositor))))); // normalize

        // deploy a malicious Log that will reenter C by making the depositor perform another Deposit
        ReentrantLog log = new ReentrantLog(address(c));

        // initialize C to use our log
        c.SetLogFile(address(log));

        // fund the depositor externally
        vm.deal(depositor, depositAmt + 1 ether);

        // depositor makes an initial deposit
        vm.startPrank(depositor);
        c.Deposit{value: depositAmt}();
        vm.stopPrank();

        // snapshot balances mapping for an arbitrary key K (we pick address(1) as an arbitrary other key)
        address K = address(1);
        uint256 beforeK = c.balances(K);

        // ensure the depositor has at least collectAmt and meets MinSum: set MinSum to 1
        c.SetMinSum(1);

        // configure the reentrant log to, when logging, cause the depositor to perform another Deposit of 1 wei
        log.configureReenter(depositor, 1);

        // now have depositor call Collect; we catch success/failure but we assert on balances(K)
        vm.startPrank(depositor);
        bool ok;
        try c.Collect(collectAmt) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The reference contract guarantees: if Collect succeeded (ok==true), then balances of other addresses K are unchanged.
        // We assert that when Collect returns successfully, balances(K) == beforeK. This holds for the reference C for all admissible inputs,
        // but the mutant with zeroing-in-Deposit plus reentrant Deposit during logging can change balances for K, causing this assertion to fail.
        if (ok) {
            assertTrue(c.balances(K) == beforeK);
        } else {
            // if Collect failed, we cannot assert preservation; still keep admissible domain wide by not assuming success
            assertTrue(true);
        }
    }
}

// Minimal adversarial Log that reenters C during AddMessage by making the configured depositor perform another Deposit
contract ReentrantLog {
    C target;
    address depositorToReenter;
    uint256 reenterAmt;
    bool configured;

    constructor(address _t) {
        target = C(_t);
    }

    function configureReenter(address who, uint256 amt) public {
        depositorToReenter = who;
        reenterAmt = amt;
        configured = true;
    }

    // signature matches AddMessage(address,uint,string)
    function AddMessage(address _adr, uint _val, string memory _data) public {
        if (configured) {
            // cause the depositor to make another deposit by calling target.Deposit via a prank
            // Since this contract is executing within the target call, it can call target.receive by sending Ether
            // Send reenterAmt wei to target so Depositor's subsequent Deposit() will process that value
            // But we cannot switch msg.sender to depositor here; instead we perform a low-level call that makes target.Deposit be invoked
            // by this contract — to have the depositor reenter, we instruct the depositor externally in test to have balance and allow direct call.
            // Simpler: have this contract call target.Deposit() to trigger Deposit logic under this contract's address,
            // which may affect balances mapping for other keys in the mutant due to zeroing. That is sufficient to distinguish behaviors.
            // send some Ether along
            (bool s,) = address(target).call{value: reenterAmt}(abi.encodeWithSignature("Deposit()"));
            require(s);
        }
    }

    // accept Ether so we can forward it to target
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // drives the contract and asserts the invariant distinguishing P and M
    // caller must send ETH to this test contract before calling run
    function run(uint depositAmount) public {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // read balance before deposit
        uint before = c.balances(address(this));

        // perform deposit on C by forwarding ETH
        c.Deposit{value: depositAmount}();

        // read balance after deposit
        uint after = c.balances(address(this));

        // On the original contract P, Deposit increases the recorded balance by exactly depositAmount (so after >= before + depositAmount).
        // The mutant removed the update, so this assertion will fail on M.
        assert(after >= before + depositAmount);
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint collectAmt, uint depositAmt) public payable {
        require(address(this).balance >= depositAmt);
        // call Collect as the given caller by using low-level call from this contract:
        // prepare calldata for Collect(uint)
        bytes memory collectCalldata = abi.encodeWithSignature("Collect(uint256)", collectAmt);
        (bool ok1,) = address(c).call(collectCalldata);
        // call Deposit sending depositAmt
        (bool ok2,) = address(c).call{value: depositAmt}(abi.encodeWithSignature("Deposit()"));
        // Observe: address(c).balance should not have decreased as a result of Deposit (i.e., Deposit does not forward Ether out)
        uint bal = address(c).balance;
        // We cannot read prior balance directly after calls, but we can assert that if Deposit call succeeded then the contract balance is at least depositAmt greater than zero OR at least not less than the amount received by this call.
        // More directly: if Deposit succeeded, c's balance must be >= depositAmt - (collectAmt) when Collect might have sent Ether out earlier; we express a general relation: after these calls, c.balance + collectAmt >= depositAmt
        // This captures that Deposit should increase or at least not be offset by an outgoing transfer greater than what was previously present.
        assert(bal + collectAmt >= depositAmt);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address payable user, uint collectAmt, uint depositAmt) public payable {
        require(depositAmt > 0);
        // Ensure this contract can receive Ether to supply depositAmt when calling c.Deposit
        require(address(this).balance >= depositAmt);

        // Call Collect as the user (we cannot change msg.sender when calling external contract here),
        // so we simulate by expecting Collect to be callable by this contract. Use the provided order.
        // Call that may change c's state.
        c.Collect(collectAmt);

        // Deposit with value depositAmt
        c.Deposit{value: depositAmt}();

        // After these operations, if Deposit was given positive ether, the public balances mapping for this contract
        // (the caller of Deposit) must be > 0 in the original contract but not in the mutant.
        uint bal = c.balances(address(this));
        assert(bal > 0);
    }
    receive() external payable {}
}
